#!/bin/bash
input=$1
outdir=$2
[[ -r "$input" ]] || { printf 'usage: copy-report INPUT OUTDIR (input unreadable)\n' >&2; exit 2; }
[[ -d "$outdir" && -w "$outdir" ]] || { printf 'output directory not writable: %s\n' "$outdir" >&2; exit 1; }
cp -- "$input" "$outdir/" || { printf 'copy failed\n' >&2; exit 1; }
printf 'copied %s\n' "$input"
